package com.youngone.mediacontrol.identity.application;

import com.youngone.mediacontrol.identity.api.HrModels;import com.youngone.mediacontrol.identity.domain.*;import com.youngone.mediacontrol.identity.infra.*;import com.youngone.mediacontrol.identity.integration.*;import org.springframework.http.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.server.ResponseStatusException;import java.time.Instant;import java.util.*;import java.nio.charset.StandardCharsets;import java.security.*;
@Service public class CsvHrImportService{
 private final HrIntegrationSourceRepository sources;private final PersonRepository persons;private final ExternalIdentityRepository externals;private final HrSyncRunRepository runs;private final HrIdentityConflictRepository conflicts;private final CsvIdentityParser parser;private final IdentityReconciliationService reconciliation;
 public CsvHrImportService(HrIntegrationSourceRepository s,PersonRepository p,ExternalIdentityRepository e,HrSyncRunRepository r,HrIdentityConflictRepository c,CsvIdentityParser parser,IdentityReconciliationService reconciliation){sources=s;persons=p;externals=e;runs=r;conflicts=c;this.parser=parser;this.reconciliation=reconciliation;}
 @Transactional public HrModels.ImportResponse importCsv(UUID sourceId,byte[] bytes,boolean dryRun,String actor){if(bytes.length>10*1024*1024)throw new ResponseStatusException(HttpStatus.PAYLOAD_TOO_LARGE,"CSV exceeds 10 MiB");HrIntegrationSource source=sources.findById(sourceId).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"HR source not found"));if(!source.isEnabled())throw new ResponseStatusException(HttpStatus.CONFLICT,"HR source disabled");if(source.getConnectorType()!=HrConnectorType.CSV_SFTP&&source.getConnectorType()!=HrConnectorType.MANUAL_UPLOAD)throw new ResponseStatusException(HttpStatus.CONFLICT,"Source is not a CSV connector");CsvIdentityParser.ParseResult parsed;try{parsed=parser.parse(bytes);}catch(IllegalArgumentException e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,e.getMessage());}if(!dryRun&&!parsed.errors().isEmpty())throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,"CSV contains validation errors; run dry-run first");long create=0,update=0,link=0,conflict=0,rejected=0,unchanged=0,applied=0;Instant started=Instant.now();for(NormalizedIdentity n:parsed.identities()){ExternalIdentity ext=externals.findBySourceIdAndExternalObjectId(sourceId,n.externalObjectId()).orElse(null);List<IdentityReconciliationService.ExistingIdentity> candidates=persons.findByAuthoritativePersonKey(n.immutablePersonKey()).stream().map(p->new IdentityReconciliationService.ExistingIdentity(p.getId(),p.getAuthoritativePersonKey(),p.getStatus())).toList();var existing=ext==null?null:new IdentityReconciliationService.ExistingIdentity(ext.getPersonId(),ext.getImmutablePersonKey(),persons.findById(ext.getPersonId()).map(Person::getStatus).orElse(EmploymentStatus.UNKNOWN));var decision=reconciliation.decide(n,existing,candidates);switch(decision.disposition()){case CREATE_PERSON->{create++;if(!dryRun){Person person=persons.save(new Person(UUID.randomUUID(),n,Instant.now()));externals.save(new ExternalIdentity(sourceId,person.getId(),n.externalObjectId(),n.immutablePersonKey(),n.sourceVersion(),n.payloadHash(),Instant.now()));applied++;}}case UPDATE_EXISTING->{if(ext!=null&&ext.getPayloadHash().equals(n.payloadHash()))unchanged++;else{update++;if(!dryRun){Person person=persons.findById(decision.personId()).orElseThrow();person.apply(n,Instant.now());ext.touch(n.sourceVersion(),n.payloadHash(),Instant.now());applied++;}}}case LINK_EXTERNAL_IDENTITY->{link++;if(!dryRun){externals.save(new ExternalIdentity(sourceId,decision.personId(),n.externalObjectId(),n.immutablePersonKey(),n.sourceVersion(),n.payloadHash(),Instant.now()));applied++;}}case REVIEW_REQUIRED->{conflict++;if(!dryRun)conflicts.save(new HrIdentityConflict(sourceId,n.externalObjectId(),n.immutablePersonKey(),decision.reasonCode(),Instant.now()));}case REJECTED->{rejected++;if(!dryRun)conflicts.save(new HrIdentityConflict(sourceId,n.externalObjectId(),n.immutablePersonKey(),decision.reasonCode(),Instant.now()));}}}
 HrSyncRun run=runs.save(new HrSyncRun(sourceId,source.getSyncMode(),parsed.identities().size(),applied,conflict+rejected,actor,sha256(bytes),dryRun,started,Instant.now()));return new HrModels.ImportResponse(run.getId(),dryRun,parsed.identities().size(),create,update,link,conflict,rejected,unchanged,parsed.errors().stream().limit(100).toList());} private String sha256(byte[] value){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(value));}catch(NoSuchAlgorithmException e){throw new IllegalStateException(e);}}
}